-- 新云端数据库初始结构；不连接 Android 本地数据库。
CREATE TABLE app_user (id VARCHAR(36) PRIMARY KEY, wechat_openid VARCHAR(128) UNIQUE, display_name VARCHAR(80) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE user_session (token_hash VARCHAR(64) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), expires_at BIGINT NOT NULL);
CREATE INDEX session_expiry_idx ON user_session(expires_at);
CREATE TABLE platform_account (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), platform VARCHAR(32) NOT NULL, display_name VARCHAR(160) NOT NULL, status VARCHAR(32) NOT NULL, encrypted_session TEXT NOT NULL, encrypted_credentials TEXT, last_sync_at BIGINT, last_error VARCHAR(300), UNIQUE(user_id,platform));
CREATE TABLE activity (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), title VARCHAR(160) NOT NULL, start_time BIGINT NOT NULL, distance_meters DOUBLE PRECISION, elapsed_seconds INTEGER, moving_seconds INTEGER, sport_type VARCHAR(32), source_platform VARCHAR(32) NOT NULL, needs_review BOOLEAN NOT NULL, review_candidate_id VARCHAR(36), primary_variant_id VARCHAR(36), created_at BIGINT NOT NULL);
CREATE INDEX activity_user_start_idx ON activity(user_id,start_time);
CREATE TABLE activity_variant (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), activity_id VARCHAR(36) NOT NULL REFERENCES activity(id), sha256 VARCHAR(64) NOT NULL, file_path VARCHAR(500) NOT NULL, metadata_json TEXT NOT NULL, quality_score INTEGER NOT NULL, UNIQUE(user_id,sha256));
CREATE TABLE platform_copy (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), activity_id VARCHAR(36) NOT NULL REFERENCES activity(id), account_id VARCHAR(36) NOT NULL REFERENCES platform_account(id), remote_id VARCHAR(200) NOT NULL, UNIQUE(activity_id,account_id), UNIQUE(account_id,remote_id));
CREATE TABLE sync_rule (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), source_platform VARCHAR(32) NOT NULL, destination_account_id VARCHAR(36) NOT NULL REFERENCES platform_account(id), enabled BOOLEAN NOT NULL, include_history BOOLEAN NOT NULL, created_at BIGINT NOT NULL, UNIQUE(user_id,source_platform,destination_account_id));
CREATE TABLE sync_job (id VARCHAR(36) PRIMARY KEY, user_id VARCHAR(36) NOT NULL REFERENCES app_user(id), kind VARCHAR(24) NOT NULL, status VARCHAR(32) NOT NULL, account_id VARCHAR(36) NOT NULL REFERENCES platform_account(id), activity_id VARCHAR(36) REFERENCES activity(id), idempotency_key VARCHAR(200) NOT NULL UNIQUE, payload_json TEXT NOT NULL, confirmation_json TEXT, attempt_count INTEGER NOT NULL, next_run_at BIGINT NOT NULL, lease_owner VARCHAR(36), lease_until BIGINT, message VARCHAR(300), created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE INDEX job_due_idx ON sync_job(status,next_run_at,lease_until);
CREATE TABLE account_lease (account_id VARCHAR(36) PRIMARY KEY REFERENCES platform_account(id), lease_owner VARCHAR(36) NOT NULL, lease_until BIGINT NOT NULL);
